INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch06$PT156-S4-Q17$batch06$, 156, 4, 17, $batch06$Parallel$batch06$, $batch06$Different cultures have independently reached the conclusion that ingesting honey daily promotes vigor and longevity. Thus, unless strong evidence emerges contradicting this conclusion, we should assume that it is true.$batch06$, $batch06$The pattern of reasoning in which one of the following is most similar to that in the argument above?$batch06$, $batch06$A$batch06$, true, $batch06$Batch 06; question text from local bank.$batch06$ FROM lr_sections s WHERE s.preptest=156 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch06$PT156-S4-Q17$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$A$batch06$, $batch06$Three engineers have inspected the bridge, and each has independently concluded that it is safe. So unless good evidence emerges that the bridge is unsafe, it should be considered safe.$batch06$, $batch06$Correct$batch06$, true FROM lr_questions q WHERE q.qid=$batch06$PT156-S4-Q17$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$A$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$B$batch06$, $batch06$Numerous studies have concluded that most people benefit from weight-training exercises. Thus, since no other form of exercise has been shown to be more beneficial, most people should be encouraged to exercise with weights.$batch06$, $batch06$Bad Premise Match$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT156-S4-Q17$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$B$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$C$batch06$, $batch06$The members of an independent group of scientists have concluded that human activities over the last century have disrupted global weather patterns. Thus, unless these scientists are working from questionable assumptions, we should conclude that their assessment is correct.$batch06$, $batch06$Bad Premise Match$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT156-S4-Q17$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$C$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$D$batch06$, $batch06$Three theater critics, none of whom had any influence on the others, said that Tales in Tokyo was not worth the price of admission. Thus, unless each of these critics happened to attend the play on the same night, it is unlikely that the play will be successful.$batch06$, $batch06$Bad Conclusion Match$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT156-S4-Q17$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$D$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$E$batch06$, $batch06$Several different physicians examined Janet, and none could agree on a diagnosis. Therefore, unless new evidence shows that Janet is unhealthy, she should instead assume that she is healthy.$batch06$, $batch06$Bad Premise Match$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT156-S4-Q17$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$E$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT156-S4-Q17$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Conclusion$batch06$, $batch06$Unless strong evidence emerges against it, we should assume honey promotes vigor and longevity.$batch06$), (1, $batch06$Evidence$batch06$, $batch06$Different cultures reached that conclusion independently.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$The pattern: several independent sources reach the same conclusion, so accept it unless good evidence emerges against it. Three pieces to match: independent agreement, the "unless contrary evidence" condition, and a recommendation to accept the conclusion.$batch06$), (3, $batch06$Goal$batch06$, $batch06$Independent sources agree, so accept their conclusion unless contrary evidence emerges.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT156-S4-Q17$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$Three engineers, independently, reach the same verdict. Unless good evidence emerges otherwise, accept it. Every piece matches.$batch06$), ($batch06$B$batch06$, $batch06$The studies are not said to be independent, and the condition ("no other form of exercise is more beneficial") is a different kind of check.$batch06$), ($batch06$C$batch06$, $batch06$One group, not several independent sources, and the condition is about their assumptions, not about contrary evidence.$batch06$), ($batch06$D$batch06$, $batch06$This predicts the play's success instead of accepting the critics' conclusion, and the "unless" condition is about attending the same night.$batch06$), ($batch06$E$batch06$, $batch06$The physicians *disagreed*. The original depends on independent sources agreeing.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT156-S4-Q17$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
